80: // Suspends a thread by attaching to it.
81: static bool SuspendThread(pid_t pid) {
82:   // This may fail if the thread has just died or debugged.
83:   errno = 0;
84:   if (sys_ptrace(PTRACE_ATTACH, pid, nullptr, nullptr) != 0 &&
85:       errno != 0) {
86:     return false;
87:   }
88:   while (true) {
89:     int status;
90:     int r = HANDLE_EINTR(sys_waitpid(pid, &status, __WALL));
91:     if (r < 0) {
92:       sys_ptrace(PTRACE_DETACH, pid, nullptr, nullptr);
93:       return false;
94:     }
95: 
96:     if (!WIFSTOPPED(status))
97:       return false;
98: 
99:     // Any signal will stop the thread, make sure it is SIGSTOP. Otherwise, this
100:     // signal will be delivered after PTRACE_DETACH, and the thread will enter
101:     // the "T (stopped)" state.
102:     if (WSTOPSIG(status) == SIGSTOP)
103:       break;
104: 
105:     // Signals other than SIGSTOP that are received need to be reinjected,
106:     // or they will otherwise get lost.
107:     r = sys_ptrace(PTRACE_CONT, pid, nullptr,
108:                    reinterpret_cast<void*>(WSTOPSIG(status)));
109:     if (r < 0)
110:       return false;
111:   }
112: #if defined(__i386) || defined(__x86_64)
113:   // On x86, the stack pointer is NULL or -1, when executing trusted code in
114:   // the seccomp sandbox. Not only does this cause difficulties down the line
115:   // when trying to dump the thread's stack, it also results in the minidumps
116:   // containing information about the trusted threads. This information is
117:   // generally completely meaningless and just pollutes the minidumps.
118:   // We thus test the stack pointer and exclude any threads that are part of
119:   // the seccomp sandbox's trusted code.
120:   user_regs_struct regs;
121:   if (sys_ptrace(PTRACE_GETREGS, pid, nullptr, &regs) == -1 ||
122: #if defined(__i386)
123:       !regs.esp
124: #elif defined(__x86_64)
125:       !regs.rsp
126: #endif
127:       ) {
128:     sys_ptrace(PTRACE_DETACH, pid, nullptr, nullptr);
129:     return false;
130:   }
131: #endif
132:   return true;
133: }
