147: bool LinuxPtraceDumper::BuildProcPath(char* path, pid_t pid,
148:                                       const char* node) const {
149:   if (!path || !node || pid <= 0)
150:     return false;
151: 
152:   size_t node_len = my_strlen(node);
153:   if (node_len == 0)
154:     return false;
155: 
156:   const unsigned pid_len = my_uint_len(pid);
157:   const size_t total_length = 6 + pid_len + 1 + node_len;
158:   if (total_length >= NAME_MAX)
159:     return false;
160: 
161:   my_memcpy(path, "/proc/", 6);
162:   my_uitos(path + 6, pid, pid_len);
163:   path[6 + pid_len] = '/';
164:   my_memcpy(path + 6 + pid_len + 1, node, node_len);
165:   path[total_length] = '\0';
166:   return true;
167: }
