169: bool LinuxPtraceDumper::CopyFromProcess(void* dest, pid_t child,
170:                                         const void* src, size_t length) {
171:   unsigned long tmp = 55;
172:   size_t done = 0;
173:   static const size_t word_size = sizeof(tmp);
174:   uint8_t* const local = (uint8_t*) dest;
175:   uint8_t* const remote = (uint8_t*) src;
176: 
177:   while (done < length) {
178:     const size_t l = (length - done > word_size) ? word_size : (length - done);
179:     if (sys_ptrace(PTRACE_PEEKDATA, child, remote + done, &tmp) == -1) {
180:       tmp = 0;
181:     }
182:     my_memcpy(local + done, &tmp, l);
183:     done += l;
184:   }
185:   return true;
186: }
