412: bool LinuxPtraceDumper::ThreadsSuspend() {
413:   if (threads_suspended_)
414:     return true;
415:   for (size_t i = 0; i < threads_.size(); ++i) {
416:     if (!SuspendThread(threads_[i])) {
417:       // If the thread either disappeared before we could attach to it, or if
418:       // it was part of the seccomp sandbox's trusted code, it is OK to
419:       // silently drop it from the minidump.
420:       if (i < threads_.size() - 1) {
421:         my_memmove(&threads_[i], &threads_[i + 1],
422:                    (threads_.size() - i - 1) * sizeof(threads_[i]));
423:       }
424:       threads_.resize(threads_.size() - 1);
425:       --i;
426:     }
427:   }
428:   threads_suspended_ = true;
429:   return threads_.size() > 0;
430: }
