432: bool LinuxPtraceDumper::ThreadsResume() {
433:   if (!threads_suspended_)
434:     return false;
435:   bool good = true;
436:   for (size_t i = 0; i < threads_.size(); ++i)
437:     good &= ResumeThread(threads_[i]);
438:   threads_suspended_ = false;
439:   return good;
440: }
