  FRIEND_TEST(LinuxCoreDumperTest, EnumerateMappings_diffname);
  FRIEND_TEST(LinuxCoreDumperTest, EnumerateMappings_merge);
  FRIEND_TEST(LinuxCoreDumperTest, EnumerateMappings_16K_padding);
#endif
};

